mapper.select:

where c.del_flag = '0'

    AND (c.config_code ilike concat('%', #{configCode}, '%') or c.version ilike concat('%', #{configCode}, '%'))


    AND c.country = #{country}


    AND c.degree = #{degree}


    AND c.publish_status = #{publishStatus}

order by c.country, c.degree, c.create_time desc, c.config_id desc
